    // marker at the function declaration.

$noteHtml = '';
  if ($stateNote !== '') {
    // State note (UNAVAILABLE / EXPIRED / GEO_BLOCK) → critical, full box
    $noteHtml = '<div class="fec-card__note">'.htmlspecialchars($stateNote, ENT_QUOTES, 'UTF-8').'</div>';
  } elseif ($fxBadge['key'] === 'issues') {
