    $cBank = 'LOWER(COALESCE('.$db->quoteName('a.bankno').', ""))';
 
    $cryptoYes = '('
      . $cCurr.' LIKE "%*btc*%" '
      . 'OR '.$cCurr.' LIKE "%*eth*%" '
      . 'OR '.$cCurr.' LIKE "%*ltc*%" '
      . 'OR '.$cCurr.' LIKE "%*usdc*%" '
      . 'OR '.$cCurr.' LIKE "%*usdt*%"'
      . ')';
    $cryptoBlocked = '('
