      . 'OR '.$cBank.' LIKE "%*eth*%" '
      . 'OR '.$cBank.' LIKE "%*ltc*%" '
      . 'OR '.$cBank.' LIKE "%*usdc*%" '
      . 'OR '.$cBank.' LIKE "%*usdt*%"'
      . ')';
    $cryptoCondition = $cryptoYes.' AND NOT '.$cryptoBlocked;
 
    $query = $db->getQuery(true);
