      array('title' => 'High Roller',        'count' => (int)$row['cnt_hr'],     'href' => '/bonuses/high-roller-bonuses',    'svg' => '<svg viewBox="0 0 24 24"><path d="M2 4l3 12h14l3-12-6 7-4-7-4 7-6-7z"/><line x1="5" y1="20" x2="19" y2="20"/></svg>'),
