      function watchSubscribeSuccess(){
        var forms = document.querySelectorAll('.fec-nl__form');
        for (var i = 0; i < forms.length; i++) {
          var st = forms[i].querySelector('.fec-nl__status');
          if (!st || st.__fec_popup_watched) continue;
