    $rankOrd     = isset($vm['frank_rank_ordinal']) ? (string)$vm['frank_rank_ordinal'] : '';
    $rankTotal   = isset($vm['frank_total_active']) ? (int)$vm['frank_total_active'] : 0;
    $reviewsN    = isset($vm['user_rating_count']) ? (int)$vm['user_rating_count'] : 0;
